    public function generateworkagreement(Request $request,$id) {
        $cand_id = $request->cand_id;
        $post = Employercandidate::where('emp_id','=',$id)->where('cand_id','=',$cand_id)->first();
        $data = [
            'emp_ar_name' => $post->emp->employer_ar_name,
            'emp_en_name' => $post->emp->employer_name,
            'emp_visa_no' => $post->emp->visa_no,
            'emp_id_no' => $post->emp->id_no,
            'salary' => $post->emp->salary,
            'emp_proffesion_en' => $post->proff->eng_name,
            'emp_profeesion_ar' => $post->proff->ar_name,
            'cand_name' => $post->cand->cand_name,
            'pass_no' => $post->cand->pass_no,
            'cand_photo' => $post->cand->photo_file,
        ];

        $food_acc = 200;
        $final_salary = ($data['salary'] - $food_acc).' + '.$food_acc.' SAR';

        $basepathSt = Basepathstatus::first();

        try {

            if (isset($basepathSt) && $basepathSt->base_path_status == 1) {
                $backfile = base_path('public/admin/assets/images/workagreement/workagreement.jpg');
            } else {
                $backfile = base_path('public_html/admin/assets/images/workagreement/workagreement.jpg');
            }

            PDF::SetCreator('Qamr International');
            PDF::SetAuthor('Qamr International');
            PDF::SetTitle($data['cand_name'].' Work Agreement');
            PDF::SetSubject($data['cand_name'].' Work Agreement');
            PDF::SetKeywords('Qamr, PDF, visa, form, guide');

            PDF::AddPage();
            PDF::Image($backfile,'','',210,297,'','','',0,false);

            // Arabci Font
            if(isset($basepathSt) && $basepathSt->base_path_status == 1){
                $emparpopins = base_path().'/public/admin/assets/custom_fonts/IBM_Plex_Sans_Arabic/IBMPlexSansArabic-Medium.ttf';
            }else{
                 $emparpopins = url('/admin/assets/custom_fonts/IBM_Plex_Sans_Arabic/IBMPlexSansArabic-Medium.ttf');
            }

            $emparpopinsfont = TCPDF_FONTS::addTTFfont($emparpopins,'','',32);
            PDF::SetFont($emparpopinsfont,'', 11,'',false);
            PDF::SetXY(40,25);
            PDF::Cell(0,0,$data['emp_ar_name']);

            if(isset($basepathSt) && $basepathSt->base_path_status == 1){
                $normalpopins = base_path().'/public/admin/assets/custom_fonts/poppins/Poppins-Medium.ttf';
            }else{
                $normalpopins = url('/admin/assets/custom_fonts/poppins/Poppins-Medium.ttf');
            }

            $normalpopinsfont = TCPDF_FONTS::addTTFfont($normalpopins,'','',32);

            PDF::SetFont($normalpopinsfont,'', 11,'',false);
            PDF::SetXY(52,35);
            PDF::Cell(0,0,$data['emp_id_no']);

            PDF::SetFont($normalpopinsfont,'', 11,'',false);
            PDF::SetXY(48,44);
            PDF::Cell(0,0,$data['cand_name']);

            PDF::SetFont($normalpopinsfont,'', 11,'',false);
            PDF::SetXY(86,56);
            PDF::Cell(0,0,$data['pass_no']);

            PDF::SetFont($normalpopinsfont,'', 11,'',false);
            PDF::SetXY(159,55);
            PDF::Cell(0,0,date('d-M-Y'));

            if ($data['cand_photo'] != '') {
                if(isset($basepathSt) && $basepathSt->base_path_status == 1){
                    $photfilepath = base_path().'/public/admin/assets/images/candidate/'.$data['cand_photo'];
                }else{
                    $photfilepath = base_path('public_html/admin/assets/images/candidate/'.$data['cand_photo']);
                }

                $photext = pathinfo($data['cand_photo'], PATHINFO_EXTENSION);


                PDF::Image($photfilepath,148,19,'35','35',$photext,'','',false,'300','',false,false,0,false,false,false);

            }

            PDF::SetFont($normalpopinsfont,'', 11,'',false);
            PDF::SetXY(78,67);
            PDF::Cell(0,0,$data['emp_proffesion_en']);

            PDF::SetFont($normalpopinsfont,'', 11,'',false);
            PDF::SetXY(58,134);
            PDF::Cell(0,0,$final_salary);

            $workagreement_file_name = $data['pass_no'].'-'.$data['cand_name'];

            ob_end_clean();

            // PDF::Output($workagreement_file_name.'_work_agreement.pdf');
            PDF::Output($workagreement_file_name.'-work-agreement.pdf','D');

        } catch (\Throwable $th) {

            return redirect()->back()->with('error','Work Agreement No Generated!');
        }

        // dd($backfile);




    }

