                }

                PDF::SetXY($cand_name_ar_cvsetting->x_axis,$cand_name_ar_cvsetting->y_axis);
                PDF::Cell(0,0,$post->arcand_name);

            }

            // Embassy Required

            if (isset($embassyreq_cvsetting)) {
                if($embassyreq_cvsetting->font_family == 'B'){
