                    // $filename = $post->reference_no.'-'.$partner->id.'-'.$candName.'-PP-'.$post->pass_no.'.pdf';
                    $filename = $post->pass_no.'-'.$post->reference_no.'-'.$partner->id.'-'.$candName.'.pdf';

                    if(isset($findcvex)){
                        // remove file from folder
                        if(isset($basepathSt) && $basepathSt->base_path_status == 1){
