    public function cvmultiplepartshare(Request $request){
        $ids = explode(",",$request->candcvs_id);

        $basepathSt = Basepathstatus::first();
        if(isset($basepathSt) && $basepathSt->base_path_status == 1){
            $backfile = base_path('public/admin/assets/images/pdf/partner');
        }else{
            $backfile = base_path('public_html/admin/assets/images/pdf/partner');
        }

        // Get Candidate List From IDS
        $cand_dets = Candidate::wherein('id',$ids)->get();
        // Get Partner Details
        $partner = Partner::find($request->partner_id);
        // Get Normal Whatsapp API
        $getAPI = Whatsappapi::where('api_for','=','booking_not')->first();

        // Actiion Based on cv_purpose Selection
        if($request->cv_purpose == 0){
            // Download CV As CV Execute
            $total_send = 0;
            $cv_file = [];

            foreach($cand_dets as $cand_det){
                // Get CV FIle
                $getCVfile = DB::table('companycvexecutes')->where('cand_id','=',$cand_det->id)->where('partner_id','=',$request->partner_id)->first();

                if(isset($getCVfile) && $getCVfile->cv_file != ''){
                    $media = $backfile.'/'.$getCVfile->cv_file;
                    if(file_exists($media)){
                        $mediaURL = url('admin/assets/images/pdf/partner/'.$getCVfile->cv_file);
                        $cv_file [] = $mediaURL;

                        $total_send++;
                    }
                }
            }

            $dataResponse = [
                'cv_purpose' => $request->cv_purpose,
                'total_files' => $total_send,
                'files' => $cv_file,
                'message' => $total_send.' CV Download'
            ];

            return response()->json($dataResponse);
        }else{
            if(isset($cand_dets) && isset($getAPI)){
                // API Details
                $instance_id = $getAPI->instance_id;
                $access_token = $getAPI->access_token;
                $api_url = $getAPI->api_url;
                $total_send = 0;

                foreach($cand_dets as $cand_det){
                    // Get CV FIle
                    $getCVfile = DB::table('companycvexecutes')->where('cand_id','=',$cand_det->id)->where('partner_id','=',$request->partner_id)->first();
                    if(isset($getCVfile) && $getCVfile->cv_file != ''){
                        //Send Whatsapp Message to partner mobile
                        $media = url('/admin/assets/images/pdf/partner/'.$getCVfile->cv_file);

                        // Check File Exists or Not if Exists then shareit
                        $mediaExists = $backfile.'/'.$getCVfile->cv_file;

                        if(file_exists($mediaExists)){
                            // Send As Per share_to
                            if($request->share_to == 1){
                                // GET Staff Data
                                $staffs = Admin::wherein('id',$request->staff_id2)->get();

                                foreach($staffs as $staff){
                                    if($staff->phone != ''){
                                        $whatsapp_message = "Dear ".$staff->name."\n\nKindly find the attached cv of candidate\n\nThanks and Regards\n\nQamr International";
                                        $send_url = $api_url."?number=".$staff->phone."&type=media&message=".urlencode($whatsapp_message)."&media_url=".$media."&filename=".$getCVfile->cv_file."&instance_id=".$instance_id."&access_token=".$access_token;
                                        $ch = curl_init();
                                        curl_setopt($ch,CURLOPT_RETURNTRANSFER,1);
                                        curl_setopt($ch,CURLOPT_URL,$send_url);
                                        $result =  curl_exec($ch);
                                        curl_close($ch);
                                        $dataResult = json_decode($result);
                                        if(isset($dataResult)){
                                            // Store logs into normal whatsapp
                                            $normalLog = new Normalwhatsapplogs();
                                            $normalLog->message_for = "Message for Share CV partner";
                                            $normalLog->message_type = "Text Message";
                                            $normalLog->template_name = "None";
                                            $normalLog->message_status = $dataResult->status;
                                            if($dataResult->status == 'error'){
                                                $normalLog->message_text = $dataResult->message;
                                            }else{
                                                $normalLog->message_text = "Message processed for send";
                                            }
                                            $normalLog->save();
                                        }
                                    }
                                }

                            }else{
                                if($partner->sharecv_per_mobile1 != ''){
                                    $whatsapp_message = "Dear ".$partner->sharecv_per_name1."\n\nKindly find the attached cv of candidate\n\nThanks and Regards\n\nQamr International";
